import{_ as a,C as d,o,c as r,E as i,a2 as s}from"./chunks/framework.BhCQlvXS.js";const _=JSON.parse('{"title":"SPEC 关键决策摘要","description":"","frontmatter":{},"headers":[],"relativePath":"spec-summary.md","filePath":"spec-summary.md","lastUpdated":1786421207000}'),l={name:"spec-summary.md"};function n(c,t,h,p,u,b){const e=d("VersionBadge");return o(),r("div",null,[i(e),t[0]||(t[0]=s(`<h1 id="spec-关键决策摘要" tabindex="-1">SPEC 关键决策摘要 <a class="header-anchor" href="#spec-关键决策摘要" aria-label="Permalink to &quot;SPEC 关键决策摘要&quot;">​</a></h1><blockquote><p>面向 AI 协作助手和资深开发者的 <strong>5 分钟速读版 SPEC</strong>。读完本文档即可掌握核心设计决策，无需每次通读 1700+ 行 SPEC.md。缺细节再去 SPEC.md 对应章节查阅。</p></blockquote><hr><h2 id="_1-项目定位与目标" tabindex="-1">1. 项目定位与目标 <a class="header-anchor" href="#_1-项目定位与目标" aria-label="Permalink to &quot;1. 项目定位与目标&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>决策</th></tr></thead><tbody><tr><td>项目原名</td><td>Dominate（后更名 Exero）</td></tr><tr><td>当前版本</td><td>V0.4.0-Beta6（最后一个 Beta，下一个 Stable）</td></tr><tr><td>目标用户</td><td>Windows 桌面用户（学生 / 上班族 / 高级用户）</td></tr><tr><td>核心理念</td><td>时间轴双模式（校园/日常）+ 快捷指令 Flow 编辑器 + 扩展市场</td></tr><tr><td>技术选型理由</td><td>Tauri v2 低内存（&lt; 50MB）/ Rust 安全高性能 / React 生态丰富</td></tr></tbody></table><hr><h2 id="_2-应用架构" tabindex="-1">2. 应用架构 <a class="header-anchor" href="#_2-应用架构" aria-label="Permalink to &quot;2. 应用架构&quot;">​</a></h2><h3 id="_2-1-五大页面" tabindex="-1">2.1 五大页面 <a class="header-anchor" href="#_2-1-五大页面" aria-label="Permalink to &quot;2.1 五大页面&quot;">​</a></h3><table tabindex="0"><thead><tr><th>页面</th><th>功能</th></tr></thead><tbody><tr><td>Dashboard 首页</td><td>系统状态概览 + 即将到来的日程 + 快捷手动触发入口</td></tr><tr><td>时间轴</td><td>日 / 周 / 月 / 年 四视图；<strong>校园模式</strong>（课表驱动）和<strong>日常模式</strong>（事件驱动）一键切换</td></tr><tr><td>快捷指令</td><td>Flow 编辑器（React Flow）+ 执行日志面板 + 触发器配置</td></tr><tr><td>性能优化</td><td>硬件监控（CPU/RAM/DISK/TEMP）+ 进程管理 + 电源计划切换</td></tr><tr><td>设置</td><td>外观 / 通用 / 扩展包 / 更新 / 关于 / 帮助 6 个子页</td></tr></tbody></table><h3 id="_2-2-前后端通信" tabindex="-1">2.2 前后端通信 <a class="header-anchor" href="#_2-2-前后端通信" aria-label="Permalink to &quot;2.2 前后端通信&quot;">​</a></h3><ul><li><strong>Tauri Commands</strong>（非 HTTP）：前端 <code>invoke(&#39;xxx_cmd&#39;, payload)</code> → Rust <code>#[tauri::command]</code></li><li><strong>事件</strong>：Rust <code>app_handle.emit()</code> → 前端 <code>listen()</code>（通知、执行进度、系统事件）</li><li><strong>协议</strong>：<code>plugin</code> 自定义协议（<code>http://plugin.localhost/</code>）服务插件前端资源</li></ul><hr><h2 id="_3-数据库" tabindex="-1">3. 数据库 <a class="header-anchor" href="#_3-数据库" aria-label="Permalink to &quot;3. 数据库&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>决策</th></tr></thead><tbody><tr><td>数据库</td><td>SQLite（rusqlite + refinery 迁移工具）</td></tr><tr><td>模式</td><td>WAL（Write-Ahead Logging），提升并发读写</td></tr><tr><td>文件路径</td><td><code>%APPDATA%\\Exero\\exero.db</code></td></tr><tr><td>编码</td><td>UTF-8</td></tr></tbody></table><h3 id="_3-1-10-张核心表" tabindex="-1">3.1 10 张核心表 <a class="header-anchor" href="#_3-1-10-张核心表" aria-label="Permalink to &quot;3.1 10 张核心表&quot;">​</a></h3><p><strong>流程数据（5 张）</strong>：</p><ol><li><code>automation_flows</code> - 快捷指令元数据</li><li><code>actions</code> - Flow 动作块（params JSON / React Flow position / fault_strategy）</li><li><code>triggers</code> - 触发器（Cron / 系统事件 / 手动）</li><li><code>execution_logs</code> - 每次动作执行记录（含 error 字段）</li><li><code>settings</code> - 设置 KV 表（key/value/type）</li></ol><p><strong>课程数据（5 张，Beta4 解耦）</strong>：</p><ol><li><code>semesters</code> - 学期定义</li><li><code>class_periods</code> - 节次时间表（节次号+开始时间+结束时间）</li><li><code>weekly_templates</code> - 周课表模板（普通周 / 特殊周）</li><li><code>courses</code> - 课程实体（归属周模板，字段含 period_index 和 time 互斥）</li><li><code>schedule_overrides</code> - 临时调课记录（单次生效）</li></ol><blockquote><p><strong>courses 双字段设计</strong>：<code>period_index</code>（课表节次号）和 <code>time</code>（精确时间戳）同时存储，拖拽改时间时两个字段互斥更新（改 period_index → 重新算 time，改 time → period_index 置 null）。</p></blockquote><hr><h2 id="_4-flow-执行引擎" tabindex="-1">4. Flow 执行引擎 <a class="header-anchor" href="#_4-flow-执行引擎" aria-label="Permalink to &quot;4. Flow 执行引擎&quot;">​</a></h2><h3 id="_4-1-执行模型" tabindex="-1">4.1 执行模型 <a class="header-anchor" href="#_4-1-执行模型" aria-label="Permalink to &quot;4.1 执行模型&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>触发（Cron/系统事件/手动）</span></span>
<span class="line"><span>  → 加载 Flow + actions 排序（BFS 生成拓扑序列）</span></span>
<span class="line"><span>  → 顺序执行每一个动作</span></span>
<span class="line"><span>    → 取 action.params（JSON）+ 填入变量</span></span>
<span class="line"><span>    → ActionExecutorRegistry::lookup 找执行器</span></span>
<span class="line"><span>    → 执行 → ActionResult(output, status)</span></span>
<span class="line"><span>    → 若 failed，按 fault_strategy 处理（Continue/Stop/Rollback/Notify）</span></span>
<span class="line"><span>  → 写 execution_logs</span></span></code></pre></div><h3 id="_4-2-21-种-actiontype-6-大类-扩展" tabindex="-1">4.2 21 种 ActionType（6 大类 + 扩展） <a class="header-anchor" href="#_4-2-21-种-actiontype-6-大类-扩展" aria-label="Permalink to &quot;4.2 21 种 ActionType（6 大类 + 扩展）&quot;">​</a></h3><p>完整列表：<a href="/Exero/docs/api/action-types">内置动作类型参考</a></p><table tabindex="0"><thead><tr><th>类别</th><th>动作数</th><th>典型</th></tr></thead><tbody><tr><td>应用与文件</td><td>4</td><td>LaunchProgram / KillProcess / OpenUrl / OpenFile</td></tr><tr><td>媒体与输入</td><td>3</td><td>SetVolume / PlaySound / SimulateKey</td></tr><tr><td>系统与电源</td><td>7</td><td>Shutdown / Reboot / LockScreen / Hibernate / Logoff / CleanTempFiles / SwitchPowerPlan</td></tr><tr><td>通知</td><td>2</td><td>ShowToast / ShowInAppNotification</td></tr><tr><td>控制流</td><td>3</td><td>IfElse（2 out）/ Loop（2 out + 2 in 迭代回环）/ SetVariable</td></tr><tr><td>脚本</td><td>2</td><td>LuaScript（用户内联）/ Extension(String)（框架内部）</td></tr></tbody></table><h3 id="_4-3-容错策略-faultstrategy" tabindex="-1">4.3 容错策略（FaultStrategy） <a class="header-anchor" href="#_4-3-容错策略-faultstrategy" aria-label="Permalink to &quot;4.3 容错策略（FaultStrategy）&quot;">​</a></h3><p>动作失败后的 4 种处理方式：</p><ul><li><code>Continue</code>（默认）：跳过，继续</li><li><code>Stop</code>：整个 Flow 中止</li><li><code>Rollback</code>：对已启动的副作用动作反向执行（如已启动的程序关闭）</li><li><code>Notify</code>：发应用内通知给用户决定</li></ul><hr><h2 id="_5-扩展系统-核心-beta5-重设计" tabindex="-1">5. 扩展系统（核心！Beta5 重设计） <a class="header-anchor" href="#_5-扩展系统-核心-beta5-重设计" aria-label="Permalink to &quot;5. 扩展系统（核心！Beta5 重设计）&quot;">​</a></h2><h3 id="_5-1-两种形态" tabindex="-1">5.1 两种形态 <a class="header-anchor" href="#_5-1-两种形态" aria-label="Permalink to &quot;5.1 两种形态&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>动作包 <code>pack_type: action</code></th><th>插件 <code>pack_type: plugin</code></th></tr></thead><tbody><tr><td>侧边栏入口</td><td>❌</td><td>✅（sidebar 独占）</td></tr><tr><td>iframe UI</td><td>❌</td><td>✅（ui.entry）</td></tr><tr><td>Flow 积木</td><td>✅（actions[]）</td><td>✅（可选附带）</td></tr><tr><td>Rust .dll</td><td>可选（自定义动作）</td><td>必选（rust_library 强制）</td></tr><tr><td>Lua 脚本</td><td>✅</td><td>✅（actions[] 支持 lua executor_type）</td></tr></tbody></table><h3 id="_5-2-三目录扫描-优先级-builtin-user-custom" tabindex="-1">5.2 三目录扫描（优先级 builtin &gt; user &gt; custom） <a class="header-anchor" href="#_5-2-三目录扫描-优先级-builtin-user-custom" aria-label="Permalink to &quot;5.2 三目录扫描（优先级 builtin &gt; user &gt; custom）&quot;">​</a></h3><ol><li><code>builtin</code> = <code>&lt;exe_dir&gt;/data/action-packs/</code>（只读）</li><li><code>user</code> = <code>%APPDATA%/Exero/action-packs/</code>（用户安装）</li><li><code>custom</code> = settings <code>extension_pack.user_dir</code>（可选自定义路径）</li></ol><h3 id="_5-3-rust-dll-接口-c-abi" tabindex="-1">5.3 Rust .dll 接口（C ABI） <a class="header-anchor" href="#_5-3-rust-dll-接口-c-abi" aria-label="Permalink to &quot;5.3 Rust .dll 接口（C ABI）&quot;">​</a></h3><p>SDK 用 <code>declare_actions!</code> 宏自动生成 4 个导出函数：</p><ul><li><code>exero_pack_init() -&gt; i32</code>（返回 0 = 成功）</li><li><code>exero_pack_cleanup()</code></li><li><code>exero_execute_action(action_id, params_json) -&gt; *const c_char</code>（NULL = 出错）</li><li><code>exero_last_error() -&gt; *const c_char</code></li></ul><p>完整细节：<a href="/Exero/docs/api/sdk">Rust SDK 参考</a></p><h3 id="_5-4-lua-沙箱" tabindex="-1">5.4 Lua 沙箱 <a class="header-anchor" href="#_5-4-lua-沙箱" aria-label="Permalink to &quot;5.4 Lua 沙箱&quot;">​</a></h3><ul><li>引擎：LuaJIT（mlua crate）</li><li>默认严格沙箱：移除 io/require/package/os.execute</li><li>宽松沙箱：manifest <code>actions[].permissions[]</code> 声明启用</li><li>超时：10 秒硬编码（Beta6）</li><li>5 个核心 API：<code>exero.log/notify/get_var/set_var/set_result</code>（通过 <code>args</code> 表访问参数）</li></ul><h3 id="_5-5-插件-ui-桥接-postmessage" tabindex="-1">5.5 插件 UI 桥接（postMessage） <a class="header-anchor" href="#_5-5-插件-ui-桥接-postmessage" aria-label="Permalink to &quot;5.5 插件 UI 桥接（postMessage）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>iframe window.exero.invoke(id, params)</span></span>
<span class="line"><span>  → postMessage({type:&#39;exero-invoke&#39;, id, actionId, params})</span></span>
<span class="line"><span>  → PluginPage 收到</span></span>
<span class="line"><span>  → invoke(&#39;execute_plugin_action&#39;, packId, actionId, params)</span></span>
<span class="line"><span>  → RustLibraryRegistry::execute</span></span>
<span class="line"><span>  → postMessage({type:&#39;exero-result&#39;, id, result|error})</span></span>
<span class="line"><span>  → Promise resolve/reject</span></span></code></pre></div><p><strong>iframe sandbox</strong>：<code>allow-scripts allow-forms allow-popups allow-modals</code>（<strong>无</strong> <code>allow-same-origin</code>、<strong>无</strong> <code>allow-top-navigation</code>）</p><hr><h2 id="_6-触发器系统" tabindex="-1">6. 触发器系统 <a class="header-anchor" href="#_6-触发器系统" aria-label="Permalink to &quot;6. 触发器系统&quot;">​</a></h2><h3 id="_6-1-三类-triggertype" tabindex="-1">6.1 三类 TriggerType <a class="header-anchor" href="#_6-1-三类-triggertype" aria-label="Permalink to &quot;6.1 三类 TriggerType&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类别</th><th>触发器</th></tr></thead><tbody><tr><td>时间类</td><td>Cron（5 字段 cron 表达式）、CourseStart（课前N分钟 / 课中 / 课后N分钟）</td></tr><tr><td>系统事件</td><td>SystemBoot / Shutdown / UserLogin / LockScreen / UsbPlug / Unplug / NetworkChange / ProcessStart / Stop</td></tr><tr><td>手动类</td><td>Manual（首页按钮 + 托盘菜单 + 快捷键）</td></tr></tbody></table><h3 id="_6-2-调度" tabindex="-1">6.2 调度 <a class="header-anchor" href="#_6-2-调度" aria-label="Permalink to &quot;6.2 调度&quot;">​</a></h3><ul><li>tokio runtime 常驻</li><li>Cron：cron crate 解析表达式 + tokio::time::sleep 循环</li><li>系统事件：WMI 订阅 + Win32 钩子（Beta6 已有部分实现）</li></ul><hr><h2 id="_7-扩展市场" tabindex="-1">7. 扩展市场 <a class="header-anchor" href="#_7-扩展市场" aria-label="Permalink to &quot;7. 扩展市场&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>决策</th></tr></thead><tbody><tr><td>分发机制</td><td>GitHub raw（<code>ansoukin/Exero</code> main 分支）</td></tr><tr><td>索引文件</td><td><code>Market/market-index.json</code>（<strong>无 BOM UTF-8</strong>）— 只下载 1 个文件展示列表</td></tr><tr><td>动作包目录</td><td><code>Market/action-packs/*.exero-pack</code></td></tr><tr><td>插件目录</td><td><code>Market/plugins/*.exero-pack</code></td></tr><tr><td>网络后备</td><td>github.com → ghproxy 镜像 → 离线</td></tr><tr><td>安装方法</td><td>市场安装 / 本地导入（设置 → 扩展包）</td></tr></tbody></table><p>完整流程：<a href="/Exero/docs/build-and-publish">构建与发布</a></p><hr><h2 id="_8-性能-内存-启动目标" tabindex="-1">8. 性能 / 内存 / 启动目标 <a class="header-anchor" href="#_8-性能-内存-启动目标" aria-label="Permalink to &quot;8. 性能 / 内存 / 启动目标&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指标</th><th>Beta6 目标</th><th>现状（Beta6 release build）</th></tr></thead><tbody><tr><td>安装包大小</td><td>&lt; 30 MB</td><td>约 22 MB</td></tr><tr><td>启动时间</td><td>&lt; 3 s</td><td>约 1.8 s</td></tr><tr><td>空闲内存</td><td>&lt; 100 MB</td><td>约 50~70 MB</td></tr><tr><td>扩展包 50+ 启动影响</td><td>&lt; 200 ms</td><td>基准测试通过</td></tr></tbody></table><hr><h2 id="_9-ai-协作开发规则-spec-§9-6-重点" tabindex="-1">9. AI 协作开发规则（SPEC §9.6 重点） <a class="header-anchor" href="#_9-ai-协作开发规则-spec-§9-6-重点" aria-label="Permalink to &quot;9. AI 协作开发规则（SPEC §9.6 重点）&quot;">​</a></h2><p>这是 AI 助手必须遵守的核心规则，原文引用：</p><ol><li><strong>不懂就问</strong>：宁可多问不要假设</li><li><strong>AI 只能修改明确涉及的模块</strong>：不要&quot;顺便&quot;改无关代码</li><li><strong>每次改动必须测试</strong>：不测试不提交</li><li><strong>核心架构改动必须文档更新同步</strong>：SPEC + API 文档 + 版本徽章</li><li><strong>硬约束必须遵守</strong>：CARGO_TARGET_DIR / cargo 手动执行 / 不轻易 pnpm add / git push 手动</li><li><strong>版本号管理</strong>：Beta 阶段大改升 Beta，小改不升；Stable 阶段 SemVer 严格</li></ol><hr><h2 id="_10-文档导航建议" tabindex="-1">10. 文档导航建议 <a class="header-anchor" href="#_10-文档导航建议" aria-label="Permalink to &quot;10. 文档导航建议&quot;">​</a></h2><p>第一次读本文档后，针对不同任务的推荐下一步：</p><table tabindex="0"><thead><tr><th>你要做的事</th><th>下一步阅读</th></tr></thead><tbody><tr><td>写一个动作包</td><td><a href="/Exero/docs/guides/action-pack">动作包开发指南</a> → <a href="/Exero/docs/api/lua-api">Lua API</a></td></tr><tr><td>写一个插件</td><td><a href="/Exero/docs/guides/plugin">插件开发指南</a> → <a href="/Exero/docs/api/sdk">Rust SDK</a> → <a href="/Exero/docs/api/bridge-api">桥接 API</a></td></tr><tr><td>引用内置动作</td><td><a href="/Exero/docs/api/action-types">内置动作类型参考</a></td></tr><tr><td>发布到市场</td><td><a href="/Exero/docs/build-and-publish">构建与发布</a></td></tr><tr><td>遇到问题</td><td><a href="/Exero/docs/troubleshooting">调试与排错</a> → <a href="/Exero/docs/faq">FAQ</a></td></tr><tr><td>改 Exero 核心代码</td><td>先读 <a href="/Exero/docs/architecture">架构概览</a> → 再读 SPEC.md 对应章节</td></tr></tbody></table>`,66))])}const m=a(l,[["render",n]]);export{_ as __pageData,m as default};
